/* rz-mega-menu.js — the site bar's mega menu (standarization/SITE_CHROME_STANDARD.md §2b).
 *
 * Owner, 2026-11-18: "elevate this with a mega menu, flush to the width of the entire nav itself … include some more
 * columns in there, and make the fourth column a visual supporter for any highlighted menu item".
 *
 * Content: data/nav-menu.json (GENERATED by tools/build-nav-menu.mjs — never hand-written here).
 * Desktop (> 768 px): one row of top-level entries; a section with groups is a <button aria-expanded aria-controls>
 *   that opens ONE panel exactly as wide as the bar: three link columns + a preview of the highlighted item.
 *   Opens on click and on hover-intent (120 ms); closes 200 ms after the pointer leaves trigger and panel, on Escape
 *   (focus back to the trigger), on Tab out, on a press outside. Opened from the keyboard: no animation.
 * Phone (<= 768 px): no panel; the same groups are accordions (one open at a time) inside the existing drawer of
 *   js/rz-mobile-nav.js.
 * The page's own links stay in the markup (crawl paths) and are only hidden ([data-rz-mm-orig]) once the menu is
 * built; if data/nav-menu.json cannot be read, nothing is hidden and the old bar keeps working.
 *
 * Loaded by js/rz-chrome.js on site-kind pages and by index.html directly. Site kind only.
 * Everything is inserted ONCE; nothing here observes the bar, so js/rz-chrome.js's MutationObserver on the bar sees
 * one batch of insertions and settles (its order()/place() only move slots, never these nodes).
 */
(function () {
  'use strict';
  if (window.__rzMegaMenu) return;
  window.__rzMegaMenu = true;

  var root = document.documentElement;
  if (root.getAttribute('data-rz-kind') === 'app') return;

  var INTENT_MS = 120, GRACE_MS = 200;
  var me = document.currentScript;
  var base = (me && me.src) ? me.src.replace(/js\/rz-mega-menu\.js(?:\?.*)?$/, '') : '';
  var CHEVRON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="6 9 12 15 18 9"></polyline></svg>';
  var phoneMq = window.matchMedia ? window.matchMedia('(max-width: 768px)') : null;

  function here() {
    var p = location.href.split('#')[0].split('?')[0];
    if (base && p.indexOf(base) === 0) p = p.slice(base.length);
    else p = p.replace(/^[a-z]+:\/\/[^/]+\//i, '');
    if (p === '' || /\/$/.test(p)) p += 'index.html';
    return decodeURIComponent(p);
  }
  var HERE = here();
  function pathOf(href) { var p = href.split('#')[0].split('?')[0]; if (p === '' || /\/$/.test(p)) p += 'index.html'; return decodeURIComponent(p); }
  function url(href) {
    if (HERE === 'index.html' && href.indexOf('index.html#') === 0) return href.slice('index.html'.length);
    return base + href;
  }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function isPhone() { return !!(phoneMq && phoneMq.matches); }

  /* ---------------- build ---------------- */
  function build(data) {
    var bar = document.querySelector('.navbar[data-rz-bar], .navbar[data-rz-float]');
    if (!bar || !data || !data.sections || bar.querySelector('.rz-mm-nav')) return;
    var box = bar.querySelector('.nav-container') || bar;
    var drawer = box.querySelector('.nav-menu, .nav-links');
    var keep = '[data-rz-slot], [data-rz-theme-toggle], .theme-toggle, .rz-auth-wrap, #rzAuthWrap, .nav-auth-wrap, .hamburger, .rz-nav-burger, .rz-nav-burger-bound';
    var hasPill = !!bar.querySelector('.nav-cta');

    var row = el('div', 'rz-mm-nav');
    row.setAttribute('data-rz-mm-nav', '');
    var acc = el(drawer && /^(UL|OL)$/.test(drawer.tagName) ? 'li' : 'div', 'rz-mm-drawer');
    var panels = [];

    data.sections.forEach(function (s) {
      var inSection = pathOf(s.href) === HERE || (s.groups || []).some(function (g) { return g.items.some(function (i) { return pathOf(i.href) === HERE; }); });
      if (!s.groups) {
        if (!(hasPill && s.id === 'contact')) {
          var a = el('a', 'rz-mm-top', s.label); a.href = url(s.href);
          if (s.minor) a.setAttribute('data-rz-mm-minor', '');
          if (pathOf(s.href) === HERE && s.href.indexOf('#') < 0) a.setAttribute('aria-current', 'page');
          row.appendChild(a);
        }
        var da = el('a', 'rz-mm-dlink', s.label); da.href = url(s.href);
        acc.appendChild(da);
        return;
      }
      var id = 'rz-mm-' + s.id;
      var t = el('button', 'rz-mm-top rz-mm-trigger');
      t.type = 'button';
      t.innerHTML = '<span></span>' + CHEVRON;
      t.firstChild.textContent = s.label;
      t.setAttribute('aria-expanded', 'false');
      t.setAttribute('aria-controls', id);
      if (inSection) t.setAttribute('data-rz-mm-here', '');
      row.appendChild(t);

      var p = el('div', 'rz-mm-panel');
      p.id = id; p.hidden = true;
      p.setAttribute('role', 'region');
      p.setAttribute('aria-label', s.label);
      var featured = null;
      s.groups.forEach(function (g) {
        var col = el('div', 'rz-mm-col');
        var lab = el('p', 'rz-mm-label', g.label); lab.id = id + '-' + panels.length + '-' + col.childNodes.length + Math.random().toString(36).slice(2, 6);
        col.appendChild(lab);
        g.items.forEach(function (it) {
          var a = el('a', 'rz-mm-item'); a.href = url(it.href);
          var tt = el('span', 'rz-mm-t', it.title);
          if (it.note) tt.appendChild(el('span', 'rz-mm-note', it.note));
          a.appendChild(tt);
          if (it.line) a.appendChild(el('span', 'rz-mm-d', it.line));
          if (pathOf(it.href) === HERE) a.setAttribute('aria-current', 'page');
          a.__rzItem = it;
          if (it.href === s.featured) featured = a;
          col.appendChild(a);
        });
        p.appendChild(col);
      });
      var fig = el('div', 'rz-mm-preview');
      fig.setAttribute('aria-live', 'polite');
      var media = el('span', 'rz-mm-media');
      var img = el('img'); img.alt = ''; img.decoding = 'async'; img.width = 1200; img.height = 630; img.hidden = true;
      var ph = el('span', 'rz-mm-ph', 'ResistanceZero');
      img.addEventListener('error', function () { img.hidden = true; ph.hidden = false; });
      img.addEventListener('load', function () { img.hidden = false; ph.hidden = true; });
      media.appendChild(img); media.appendChild(ph);
      var pt = el('p', 'rz-mm-pt'), pd = el('p', 'rz-mm-pd');
      var open = el('a', 'rz-mm-open'); open.innerHTML = 'Open <span aria-hidden="true">&nbsp;→</span>';
      fig.appendChild(media); fig.appendChild(pt); fig.appendChild(pd); fig.appendChild(open);
      p.appendChild(fig);
      p.__rz = { trigger: t, img: img, ph: ph, pt: pt, pd: pd, open: open, featured: featured || p.querySelector('.rz-mm-item') };
      t.__rzPanel = p;
      panels.push(p);

      /* phone: the same groups as accordions */
      acc.appendChild(el('p', 'rz-mm-sec', s.label));
      s.groups.forEach(function (g, gi) {
        var b = el('button', 'rz-mm-acc-btn');
        b.type = 'button';
        b.innerHTML = '<span></span>' + CHEVRON;
        b.firstChild.textContent = g.label;
        var lid = id + '-acc-' + gi;
        b.setAttribute('aria-expanded', 'false');
        b.setAttribute('aria-controls', lid);
        var list = el('div', 'rz-mm-acc-list'); list.id = lid; list.hidden = true;
        g.items.forEach(function (it) {
          var a = el('a'); a.href = url(it.href);
          a.appendChild(el('span', 'rz-mm-t', it.title));
          if (it.line) a.appendChild(el('span', 'rz-mm-d', it.line));
          if (pathOf(it.href) === HERE) a.setAttribute('aria-current', 'page');
          list.appendChild(a);
        });
        acc.appendChild(b); acc.appendChild(list);
      });
    });

    /* hide the page's own links (kept in the markup), insert ours — once */
    if (drawer) {
      for (var c = drawer.firstElementChild; c; c = c.nextElementSibling) {
        if (!(c.matches(keep) || c.querySelector(keep))) c.setAttribute('data-rz-mm-orig', '');
      }
      drawer.insertBefore(acc, drawer.firstChild);
    }
    var anchor = drawer && drawer.parentNode === box ? drawer : (box.firstElementChild ? box.firstElementChild.nextSibling : null);
    box.insertBefore(row, anchor);
    for (var i = 0; i < panels.length; i++) bar.appendChild(panels[i]);

    var search = bar.querySelector('[data-rz-slot="search"], #navSearchBtn');
    if (search) search.setAttribute('data-rz-kbd', /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent || '') ? '⌘K' : 'Ctrl K');

    root.setAttribute('data-rz-mm', 'ready');
    wire(bar, row, panels, acc);
  }

  /* ---------------- behaviour ---------------- */
  function wire(bar, row, panels, acc) {
    var current = null, openTimer = 0, closeTimer = 0;

    function preview(p, a) {
      var r = p.__rz, it = a && a.__rzItem;
      if (!it) return;
      var lit = p.querySelectorAll('[data-rz-mm-lit]');
      for (var i = 0; i < lit.length; i++) lit[i].removeAttribute('data-rz-mm-lit');
      a.setAttribute('data-rz-mm-lit', '');
      r.pt.textContent = it.title;
      r.pd.textContent = it.line || '';
      r.open.href = a.href;
      r.open.setAttribute('aria-label', 'Open ' + it.title);
      if (it.image) {
        var src = url(it.image);
        if (r.img.getAttribute('src') !== src) { r.img.hidden = true; r.ph.hidden = false; r.img.src = src; }
        else if (r.img.complete && r.img.naturalWidth) { r.img.hidden = false; r.ph.hidden = true; }
      } else {
        r.img.removeAttribute('src'); r.img.hidden = true; r.ph.hidden = false;
      }
    }
    function show(p, instant) {
      clearTimeout(closeTimer); clearTimeout(openTimer);
      if (current && current !== p) hide(current, true);
      p.classList.toggle('rz-mm-instant', !!instant);
      p.hidden = false;
      p.__rz.trigger.setAttribute('aria-expanded', 'true');
      if (current !== p) preview(p, p.__rz.featured);
      current = p;
    }
    function hide(p, instant) {
      if (!p) return;
      if (instant) p.classList.add('rz-mm-instant');
      p.hidden = true;
      p.__rz.trigger.setAttribute('aria-expanded', 'false');
      if (current === p) current = null;
    }
    function closeAll(instant) { clearTimeout(openTimer); clearTimeout(closeTimer); if (current) hide(current, instant); }
    function items(p) { return Array.prototype.slice.call(p.querySelectorAll('.rz-mm-col')).map(function (c) { return Array.prototype.slice.call(c.querySelectorAll('.rz-mm-item')); }).concat([[p.__rz.open]]); }
    function focusFirst(p) { var a = p.querySelector('.rz-mm-item'); if (a) { a.focus(); preview(p, a); } }

    var triggers = Array.prototype.slice.call(row.querySelectorAll('.rz-mm-trigger'));
    triggers.forEach(function (t) {
      var p = t.__rzPanel;
      t.addEventListener('click', function (e) {
        var kb = e.detail === 0;
        if (current === p && !p.hidden) { hide(p, kb); return; }
        show(p, kb);
        if (kb) focusFirst(p);
      });
      t.addEventListener('keydown', function (e) {
        if (e.key === 'ArrowDown') { e.preventDefault(); show(p, true); focusFirst(p); }
        else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
          var tops = Array.prototype.slice.call(row.querySelectorAll('.rz-mm-top'));
          var k = tops.indexOf(t) + (e.key === 'ArrowRight' ? 1 : -1);
          if (k >= 0 && k < tops.length) { e.preventDefault(); tops[k].focus(); }
        }
      });
      t.addEventListener('pointerenter', function (e) {
        if (e.pointerType !== 'mouse' || isPhone()) return;
        clearTimeout(closeTimer); clearTimeout(openTimer);
        if (current === p) return;
        openTimer = setTimeout(function () { show(p, false); }, INTENT_MS);
      });
      t.addEventListener('pointerleave', function (e) {
        if (e.pointerType !== 'mouse') return;
        clearTimeout(openTimer);
        closeTimer = setTimeout(function () { hide(p, false); }, GRACE_MS);
      });
    });

    panels.forEach(function (p) {
      p.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse') { clearTimeout(closeTimer); clearTimeout(openTimer); } });
      p.addEventListener('pointerleave', function (e) {
        if (e.pointerType !== 'mouse') return;
        closeTimer = setTimeout(function () { hide(p, false); }, GRACE_MS);
      });
      p.addEventListener('pointerover', function (e) { var a = e.target.closest && e.target.closest('.rz-mm-item'); if (a) preview(p, a); });
      p.addEventListener('focusin', function (e) { var a = e.target.closest && e.target.closest('.rz-mm-item'); if (a) preview(p, a); });
      p.addEventListener('keydown', function (e) {
        var cols = items(p), ci = -1, ri = -1;
        for (var i = 0; i < cols.length; i++) { var k = cols[i].indexOf(document.activeElement); if (k >= 0) { ci = i; ri = k; } }
        if (e.key === 'Escape') { e.preventDefault(); hide(p, true); p.__rz.trigger.focus(); return; }
        if (ci < 0) return;
        var to = null;
        if (e.key === 'ArrowDown') to = cols[ci][Math.min(ri + 1, cols[ci].length - 1)];
        else if (e.key === 'ArrowUp') { if (ri === 0) { e.preventDefault(); p.__rz.trigger.focus(); return; } to = cols[ci][ri - 1]; }
        else if (e.key === 'ArrowRight' && ci < cols.length - 1) to = cols[ci + 1][Math.min(ri, cols[ci + 1].length - 1)];
        else if (e.key === 'ArrowLeft' && ci > 0) to = cols[ci - 1][Math.min(ri, cols[ci - 1].length - 1)];
        else if (e.key === 'Home') to = cols[ci][0];
        else if (e.key === 'End') to = cols[ci][cols[ci].length - 1];
        if (to) { e.preventDefault(); to.focus(); }
      });
    });

    /* Tab out of trigger + panel closes; a press outside the bar closes; Escape anywhere closes */
    bar.addEventListener('focusout', function (e) {
      if (!current) return;
      var to = e.relatedTarget;
      if (to && (current.contains(to) || to === current.__rz.trigger)) return;
      if (!to && document.activeElement && current.contains(document.activeElement)) return;
      hide(current, true);
    });
    document.addEventListener('pointerdown', function (e) { if (current && !bar.contains(e.target)) closeAll(true); });
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Escape' || !current) return;
      var t = current.__rz.trigger; closeAll(true);
      if (bar.contains(document.activeElement) || document.activeElement === document.body) t.focus();
    });
    if (phoneMq) { var onMq = function () { closeAll(true); }; if (phoneMq.addEventListener) phoneMq.addEventListener('change', onMq); else if (phoneMq.addListener) phoneMq.addListener(onMq); }

    /* phone accordions: one open at a time */
    acc.addEventListener('click', function (e) {
      var b = e.target.closest && e.target.closest('.rz-mm-acc-btn');
      if (!b) return;
      e.preventDefault();
      var open = b.getAttribute('aria-expanded') !== 'true';
      var all = acc.querySelectorAll('.rz-mm-acc-btn');
      for (var i = 0; i < all.length; i++) {
        var on = open && all[i] === b;
        all[i].setAttribute('aria-expanded', on ? 'true' : 'false');
        var l = document.getElementById(all[i].getAttribute('aria-controls'));
        if (l) l.hidden = !on;
      }
    });
  }

  function start() {
    var x = new XMLHttpRequest();
    x.open('GET', base + 'data/nav-menu.json?v=19974c42', true);
    x.setRequestHeader('Cache-Control', 'no-cache');
    x.onload = function () {
      if (x.status < 200 || x.status >= 300) return;
      try { build(JSON.parse(x.responseText)); } catch (e) { /* bad menu data: the page's own links stay */ if (window.console) console.warn('rz-mega-menu: menu not built', e); }
    };
    x.send();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
